"""Local workflow illustration with pause and reduced-motion support."""

import streamlit as st

STORY = "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>FORGE investigation workflow</title>\n<style>\n:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101816;color:#eff3eb;font-family:Arial,sans-serif}canvas{display:block;width:100%;height:auto}button{position:absolute;right:18px;bottom:12px;border:1px solid #65766a;border-radius:6px;background:#192521;color:#eff3eb;padding:7px 12px;font:12px Arial;cursor:pointer}button:hover{border-color:#ddba76}button:focus-visible{outline:2px solid #ddba76;outline-offset:3px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(prefers-reduced-motion:reduce){canvas{animation:none}}\n</style>\n<canvas width=\"1400\" height=\"520\" role=\"img\" aria-label=\"Workflow illustration. Recorded sensor readings pass through anomaly scoring, passage retrieval, citation checks and human review before export.\"></canvas>\n<p class=\"sr-only\">This is an illustration of the implemented workflow, not a live investigation. No machine actions are taken.</p>\n<button type=\"button\" id=\"motion\">Pause animation</button>\n<script>\nconst canvas=document.querySelector('canvas'),c=canvas.getContext('2d'),compact=document.documentElement.hasAttribute('data-compact');\nconst C={bg:'#101816',panel:'#18231f',line:'#3d5046',muted:'#a2b3a8',text:'#eff3eb',gold:'#ddba76',green:'#91c8ad',coral:'#ef937b'};\nconst ease=x=>1-Math.pow(1-Math.max(0,Math.min(1,x)),3);\nfunction text(s,x,y,size=20,color=C.text,weight=400){c.fillStyle=color;c.font=`${weight} ${size}px Arial`;c.fillText(s,x,y)}\nfunction line(x1,y1,x2,y2,color=C.line,w=1){c.strokeStyle=color;c.lineWidth=w;c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.stroke()}\nfunction box(x,y,w,h,color=C.panel,border=C.line){c.fillStyle=color;c.strokeStyle=border;c.lineWidth=1;c.beginPath();c.roundRect(x,y,w,h,12);c.fill();c.stroke()}\nfunction path(points,color=C.line,width=2){c.strokeStyle=color;c.lineWidth=width;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke()}\nfunction dot(x,y,r,color){c.fillStyle=color;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill()}\nfunction route(points,progress){path(points);let lengths=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1]));let distance=ease(progress)*lengths.reduce((a,b)=>a+b,0);for(let i=0;i<lengths.length;i++){if(distance<=lengths[i]){let q=distance/lengths[i],p=points[i],n=points[i+1];dot(p[0]+(n[0]-p[0])*q,p[1]+(n[1]-p[1])*q,5,C.gold);break}distance-=lengths[i]}}\nfunction waveform(x,y,w,h,amount=1,color=C.gold){c.save();c.beginPath();c.rect(x,y-h,w*Math.max(.01,amount),h*2);c.clip();c.strokeStyle=color;c.lineWidth=2;c.beginPath();for(let i=0;i<=180;i++){let v=Math.sin(i*.28)*.14+Math.sin(i*1.13)*.08+(i>80&&i<135?Math.sin(i*.42)*.55+.17:0);let px=x+i/180*w,py=y-v*h;i?c.lineTo(px,py):c.moveTo(px,py)}c.stroke();c.restore()}\nfunction check(x,y,amount){c.save();c.beginPath();c.rect(x-2,y-16,30*amount,32);c.clip();path([[x,y],[x+7,y+7],[x+22,y-10]],C.green,3);c.restore()}\nwindow.renderForge=function(seconds){const t=Math.min(seconds,10.5);c.fillStyle=C.bg;c.fillRect(0,0,1400,520);\nif(compact){const active=t<2?0:t<4?1:t<6?2:3;const labels=['Read sensors','Score the recording','Retrieve evidence','Review the draft'];const xs=[24,370,716,1062];xs.forEach((x,i)=>{text(labels[i],x,33,23,i===active?C.gold:C.muted,600);line(x,49,x+285,49,i===active?C.gold:C.line,2)});waveform(24,99,275,25,ease((t+.3)/1.7));for(let i=0;i<22;i++){c.fillStyle=i>8&&i<16?C.coral:C.line;c.fillRect(370+i*12,121,5,-(12+(i>8&&i<16?30:5))*ease((t-1.5-i*.025)/.6))}for(let i=0;i<3;i++){line(716,80+i*18,968-i*20,80+i*18,t>3.5+i*.2?C.gold:C.line,2);text('['+(i+1)+']',980,86+i*18,15,C.muted)}for(let i=0;i<3;i++){line(1103,80+i*18,1325-i*20,80+i*18,C.line,2);check(1064,76+i*18,ease((t-5.8-i*.22)/.5))}for(let i=0;i<3;i++)route([[xs[i]+295,93],[xs[i]+327,93]],(t-1.3-i*1.9)/.7);text('Workflow illustration',24,172,15,C.muted);return;}\ntext('FORGE',42,60,32,C.text,700);text('A recording becomes an investigation',42,105,27,C.text,400);text('WORKFLOW ILLUSTRATION',1110,59,12,C.muted,600);line(42,130,1358,130);\nconst active=t<2?0:t<4?1:t<6?2:3;\nconst stages=['01  RECORDING','02  DETECTION','03  EVIDENCE','04  REVIEW'];const xs=[42,375,720,1065];stages.forEach((s,i)=>{text(s,xs[i],173,13,i===active?C.gold:C.muted,600);line(xs[i],187,xs[i]+265,187,i<=active?C.gold:C.line,2)});\nbox(42,220,265,190);text('Eight sensor channels',60,250,19,C.text,600);text('Recorded pump measurements',60,276,13,C.muted);line(60,337,287,337,C.line);waveform(60,336,227,47,ease((t+.3)/1.7));text('SKAB laboratory data',60,391,13,C.muted);\nbox(375,220,265,190,C.panel,active===1?C.gold:C.line);text('Score + persistence',393,250,19,C.text,600);text('Model and alert threshold',393,276,13,C.muted);\nfor(let i=0;i<19;i++){let h=12+Math.sin(i*.8)*8+(i>8&&i<15?42:0);c.fillStyle=i>8&&i<15?C.coral:C.line;c.fillRect(393+i*12,363-h,6,h*ease((t-1.5-i*.025)/.6))}c.setLineDash([4,4]);line(393,331,617,331,C.gold);c.setLineDash([]);text(t>3?'Persistent alert found':'Reading the signal',393,391,13,t>3?C.coral:C.muted);\nroute([[307,313],[341,313],[341,313],[375,313]],(t-1.4)/.7);\nbox(720,220,265,190,C.panel,active===2?C.gold:C.line);text('Find supporting notes',738,250,19,C.text,600);text('TF-IDF retrieval',738,276,13,C.muted);\nfor(let i=0;i<3;i++){const a=ease((t-3.6-i*.13)/.6);c.globalAlpha=.28+.72*a;line(740,310+i*24,942-i*18,310+i*24,i===0?C.gold:C.muted,3);text('['+(i+1)+']',945,315+i*24,13,C.gold);c.globalAlpha=1}text('Passage, version, source',738,391,13,C.muted);\nroute([[640,313],[680,313],[680,313],[720,313]],(t-3.2)/.6);\nbox(1065,220,265,190,C.panel,active===3?C.gold:C.line);text('Review the draft',1083,250,19,C.text,600);text('Checks linked to citations',1083,276,13,C.muted);\nfor(let i=0;i<3;i++){line(1120,310+i*23,1305-i*20,310+i*23,C.line,3);check(1085,307+i*23,ease((t-5.8-i*.22)/.5))}text(t>8?'Ready for a person to review':'Verify source support',1083,391,13,t>8?C.green:C.muted);\nroute([[985,313],[1026,313],[1026,313],[1065,313]],(t-5.1)/.65);\n// A second route makes the corpus dependency explicit while keeping one focal action.\nline(854,411,854,449,C.line);text('Versioned analytical corpus',732,473,13,C.muted);dot(854,425+Math.sin(t*.8)*4,2,C.green);\nconst captions=['Inspect the measurements in time order.','Apply the saved detector and persistence rule.','Retrieve relevant passages from the local corpus.','Verify citations, then leave the decision to a reviewer.'];text(captions[active],42,477,17,C.text);text('Local workflow / Markdown + JSON export',42,502,12,C.muted);\n};\nconst media=matchMedia('(prefers-reduced-motion: reduce)');let paused=media.matches,time=paused?10:0,previous=null;const button=document.querySelector('button');\nfunction label(){button.textContent=paused?'Play animation':'Pause animation';button.setAttribute('aria-pressed',String(!paused))}label();button.onclick=()=>{paused=!paused;if(!paused&&time>=10.5)time=0;label()};\nmedia.addEventListener('change',()=>{paused=media.matches;if(paused)time=10;label();renderForge(time)});\nfunction tick(now){if(previous!==null&&!paused&&!document.hidden)time=(time+Math.min((now-previous)/1000,.05))%12;previous=now;renderForge(time);requestAnimationFrame(tick)}\nif(!location.search.includes('capture'))requestAnimationFrame(tick);else{button.style.display='none';renderForge(10)}\n</script></html>\n"


def render_workflow():
    compact = STORY.replace('<html lang="en">', '<html lang="en" data-compact>').replace(
        'height="520"', 'height="180"'
    )
    compact = compact.replace(
        "</style>",
        "@media(max-width:540px){canvas{display:none}button{display:none}.sr-only{position:static;width:auto;height:auto;clip-path:none;margin:8px 0;font-size:14px;line-height:1.6}}</style>",
    )
    compact = compact.replace(
        "This is an illustration of the implemented workflow, not a live investigation. No machine actions are taken.",
        "The workflow scores the recording, retrieves supporting passages, and checks citations before human review.",
    )
    st.iframe(compact, height=145)
